@dataclass
class OracleInputPart:
    """One certified input subset and the oracle facts proved for it."""

    part_id: str
    region: dict
    holes: dict
    witness: dict
    representative_ce: dict = None
    representative_claim: dict = None
    assertions: tuple = ()
    depth: int = 0


def make_oracle_input_part(part_id,
                           region,
                           holes,
                           witness,
                           representative_ce=None,
                           representative_claim=None,
                           assertions=(),
                           depth=0):
    """Normalize and validate one JSON-compatible oracle input part."""
    normalized_region = {}
    normalized_holes = {}
    normalized_witness = {}
    normalized_representative_ce = None
    for name, bounds in sorted((region or {}).items()):
        if not isinstance(bounds, (list, tuple)) or len(bounds) != 2:
            raise ValueError(f"oracle input part {part_id}: invalid bounds for {name}")
        lo, hi = (int(str(value), 0) for value in bounds)
        if lo > hi:
            raise ValueError(f"oracle input part {part_id}: empty interval for {name}")
        normalized_region[str(name)] = (lo, hi)
        excluded = sorted({
            int(str(value), 0)
            for value in (holes or {}).get(name, ()) if lo <= int(str(value), 0) <= hi
        })
        if excluded:
            normalized_holes[str(name)] = tuple(excluded)
        if name not in (witness or {}):
            raise ValueError(f"oracle input part {part_id}: witness lacks {name}")
        value = int(str(witness[name]), 0)
        if value < lo or value > hi or value in excluded:
            raise ValueError(f"oracle input part {part_id}: witness is outside {name}")
        normalized_witness[str(name)] = value
    if representative_ce is not None:
        if not isinstance(representative_ce, dict):
            raise ValueError(f"oracle input part {part_id}: representative CE is not an object")
        normalized_representative_ce = {}
        for raw_name, raw_value in representative_ce.items():
            name = str(raw_name)
            if not name:
                raise ValueError(f"oracle input part {part_id}: representative CE has empty key")
            normalized_representative_ce[name] = str(raw_value)

        def representative_value_for(coord_name):
            if coord_name in normalized_representative_ce:
                return normalized_representative_ce[coord_name]
            if not coord_name.startswith("state."):
                return None
            wanted = coord_name[len("state."):]
            normalized = lambda value: re.sub(r"\$\d+(?=\.|\[|$)", "", str(value))
            matches = [
                value for key, value in normalized_representative_ce.items()
                if key.startswith("state.") and normalized(key[len("state."):]) == wanted
            ]
            return matches[0] if len(matches) == 1 else None

        for name, value in normalized_witness.items():
            ce_raw_value = representative_value_for(name)
            if ce_raw_value is None:
                raise ValueError(f"oracle input part {part_id}: representative CE lacks {name}")
            try:
                ce_value = int(str(ce_raw_value), 0)
            except (TypeError, ValueError) as exc:
                raise ValueError(
                    f"oracle input part {part_id}: representative CE has non-scalar {name}") from exc
            if ce_value != value:
                raise ValueError(
                    f"oracle input part {part_id}: representative CE differs on {name}")
    if representative_claim is not None and not isinstance(representative_claim, dict):
        raise ValueError(f"oracle input part {part_id}: representative claim is not an object")
    return OracleInputPart(str(part_id), normalized_region, normalized_holes,
                           normalized_witness, normalized_representative_ce,
                           dict(representative_claim) if representative_claim is not None else None,
                           tuple(assertions or ()), int(depth))


def split_oracle_input_part(part, counterexample, coordinate_order=None):
    """Split ``part`` at a refuting input while preserving an exact union.

    The child containing the old representative keeps that witness. The other
    child receives the complete refuting input as its representative. Return
    ``(witness_child, refutation_child, coordinate)`` or ``None`` when no
    renderable coordinate separates the two inputs.
    """
    if not isinstance(part, OracleInputPart):
        raise TypeError("oracle input split requires OracleInputPart")
    if isinstance(counterexample, dict) and isinstance(counterexample.get("coordinates"), dict):
        coordinate_values = counterexample.get("coordinates")
        refuting_ce = counterexample.get("ce")
        refuting_claim = counterexample.get("claim")
    else:
        coordinate_values = counterexample or {}
        refuting_ce = counterexample if isinstance(counterexample, dict) else None
        refuting_claim = None
    try:
        refuting = {
            name: int(str(coordinate_values[name]), 0)
            for name in part.region
        }
    except (KeyError, TypeError, ValueError):
        return None
    for name, value in refuting.items():
        lo, hi = part.region[name]
        if value < lo or value > hi or value in part.holes.get(name, ()):
            return None
    ordered = []
    for name in list(coordinate_order or ()) + sorted(part.region):
        if name in part.region and name not in ordered:
            ordered.append(name)
    coordinate = next(
        (name for name in ordered if part.witness[name] != refuting[name]), None)
    if coordinate is None:
        return None
    lo, hi = part.region[coordinate]
    witness_value = part.witness[coordinate]
    refuting_value = refuting[coordinate]
    if witness_value < refuting_value:
        witness_bounds = (lo, refuting_value - 1)
        refuting_bounds = (refuting_value, hi)
    else:
        refuting_bounds = (lo, refuting_value)
        witness_bounds = (refuting_value + 1, hi)
    if witness_bounds[0] > witness_bounds[1] or refuting_bounds[0] > refuting_bounds[1]:
        return None

    def child(suffix, bounds, representative, representative_ce, representative_claim):
        region = dict(part.region)
        region[coordinate] = bounds
        holes = {
            name: tuple(value for value in values
                        if region[name][0] <= value <= region[name][1])
            for name, values in part.holes.items()
        }
        holes = {name: values for name, values in holes.items() if values}
        return make_oracle_input_part(f"{part.part_id}.{suffix}", region, holes,
                                      representative,
                                      representative_ce=representative_ce,
                                      representative_claim=representative_claim,
                                      assertions=part.assertions,
                                      depth=part.depth + 1)

    return (child("w", witness_bounds, part.witness, part.representative_ce,
                  part.representative_claim),
            child("r", refuting_bounds, refuting, refuting_ce, refuting_claim), coordinate)


def refine_oracle_candidate_parts(part,
                                  candidate,
                                  family,
                                  initial_verdict,
                                  initial_refutation,
                                  verifier,
                                  coordinate_order=None,
                                  max_parts=4,
                                  max_depth=2):
    """Refine R1/R2.1/R2.3 over certified input subsets.

    ``verifier(child, candidate)`` returns ``(verdict, refutation)``. A proved
    child receives the candidate; an undecided or unsplittable child remains
    covered without it. The child containing the known refutation is retained
    immediately without the candidate, while the witness child is rechecked.
    """
    if family not in ("R1", "R2.1", "R2.3"):
        raise ValueError(f"input-part refinement is unsupported for {family}")
    if not isinstance(part, OracleInputPart):
        raise TypeError("oracle refinement requires OracleInputPart")
    max_parts = max(1, int(max_parts))
    max_depth = max(0, int(max_depth))
    results = []
    queries = []

    def retain(current, proved):
        assertions = current.assertions
        if proved and candidate not in assertions:
            assertions += (candidate,)
        results.append(
            make_oracle_input_part(current.part_id, current.region, current.holes,
                                   current.witness,
                                   representative_ce=current.representative_ce,
                                   representative_claim=current.representative_claim,
                                   assertions=assertions,
                                   depth=current.depth))

    current = part
    verdict = str(initial_verdict or "UNDECIDED")
    refutation = initial_refutation
    while True:
        if verdict == "HOLDS":
            retain(current, True)
            break
        if verdict != "REFUTED" or current.depth >= max_depth or len(results) + 2 > max_parts:
            retain(current, False)
            break
        split = split_oracle_input_part(current, refutation, coordinate_order)
        if split is None:
            retain(current, False)
            break
        witness_child, refuting_child, coordinate = split
        retain(refuting_child, False)
        queries.append({
            "parent_part_id": current.part_id,
            "part_id": witness_child.part_id,
            "coordinate": coordinate,
            "candidate": candidate,
            "family": family,
        })
        verdict, refutation = verifier(witness_child, candidate)
        verdict = str(verdict or "UNDECIDED")
        current = witness_child
    return sorted(results, key=lambda value: value.part_id), queries


def refine_oracle_parts(parts,
                        candidates,
                        verifier,
                        coordinate_order=None,
                        max_parts=4,
                        max_depth=2):
    """Apply each R1/R2.1/R2.3 candidate to every retained input part."""
    current_parts = list(parts or [])
    all_queries = []
    for candidate, family in candidates or ():
        next_parts = []
        for part in current_parts:
            verdict, refutation = verifier(part, candidate)
            all_queries.append({
                "part_id": part.part_id,
                "candidate": candidate,
                "family": family,
                "initial": True,
            })
            remaining = max(1, int(max_parts) - len(next_parts))
            refined, queries = refine_oracle_candidate_parts(
                part,
                candidate,
                family,
                verdict,
                refutation,
                verifier,
                coordinate_order,
                remaining,
                max_depth)
            next_parts.extend(refined)
            all_queries.extend(queries)
        current_parts = sorted(next_parts, key=lambda value: value.part_id)
    return current_parts, all_queries


def oracle_part_assert_spec(base_spec, part, variable=None, exact_vars=None,
                            variables=None):
    """Build the assertion query for one certified oracle input part.

    The path identity and establishment policy come from ``base_spec``.  Only
    the input region is narrowed.  Holes remain exclusions rather than being
    silently filled back into the child interval.

    ``variables`` names EVERY state-exact variable the query should carry: one
    ESBMC run evaluates the complete R1 ladder of each named variable, so the
    part is asked about all of them at once instead of one process per
    variable.  ``variable`` is the single-variable form kept for callers that
    have exactly one.
    """
    if not isinstance(part, OracleInputPart):
        raise TypeError("oracle assertion query requires OracleInputPart")
    spec = json.loads(json.dumps(base_spec or {}))
    pinned = []
    for entry in spec.get("region", []):
        if not isinstance(entry, dict) or not entry.get("name"):
            continue
        name = str(entry["name"])
        if name not in part.region:
            pinned.append(entry)
    narrowed = []
    for name, (lo, hi) in sorted(part.region.items()):
        entry = {"name": name, "lo": str(lo), "hi": str(hi)}
        excluded = part.holes.get(name, ())
        if excluded:
            entry["holes"] = [str(value) for value in excluded]
        narrowed.append(entry)
    spec["region"] = narrowed + pinned
    if exact_vars is not None:
        spec["candidate_policy"] = "exact"
        spec["vars"] = json.loads(json.dumps(exact_vars))
    elif variables:
        spec["vars_policy"] = "state-exact"
        spec["vars"] = [{"name": str(name)} for name in variables]
    elif variable is not None:
        spec["vars_policy"] = "state-exact"
        spec["vars"] = [{"name": str(variable)}]
    return spec


# The smallest ESBMC budget under which an oracle-part query is still worth
# launching.  MEASURED (campaign-full-v2, acfix_llama3_017 getDrugsSinceLastCollect
# pf529, 2026-08-20): once the PUT deadline had passed, `esbmc_budget` floored at
# 1 s and the refinement loop launched 400+ one-second queries of the SAME spec,
# every one killed before its ladder summary and every one answered UNDECIDED.
ORACLE_PART_MIN_BUDGET_S = 10


def oracle_part_query_plan(candidate, candidate_families, exact_vars, var_name_of):
    """Decide the ONE query that answers ``candidate`` on a part -- and, with it,
    every other candidate the same run decides for free.

    Returns ``(signature, spec_kwargs)``.  ``signature`` identifies the query
    independently of the candidate that triggered it, so a part whose query has
    already run (or already failed) is never asked the identical question again:

    * an R2 candidate is carried by its own exact var-set, which already lists
      every candidate of that R2 spec -- signature = that var-set;
    * an R1 candidate is answered by a state-exact query, and one such query
      evaluates the full R1 ladder of EVERY named variable, so the plan names
      all R1 variables of the row at once -- signature = that variable tuple.
    """
    exact = (exact_vars or {}).get(candidate)
    if exact is not None:
        return (("exact", json.dumps(exact, sort_keys=True)), {"exact_vars": exact})
    names = []
    for other, family in candidate_families or ():
        if family != "R1" or (exact_vars or {}).get(other) is not None:
            continue
        name = str(var_name_of(other[0]))
        if name not in names:
            names.append(name)
    own = str(var_name_of(candidate[0]))
    if own not in names:
        names.append(own)
    return (("state-exact", tuple(names)), {"variables": names})


def oracle_part_candidate_verdict(rows, summary, candidate, refutations=None):
    """Return the final verifier answer for exactly one oracle candidate."""
    if summary is None or not isinstance(candidate, (list, tuple)) or len(candidate) != 2:
        return "UNDECIDED", None
    wanted = (str(candidate[0]), canonical_oracle_rung_text(candidate[1]))
    matches = [(verdict, (refutations or {}).get(wanted)) for var, text, verdict in rows
               if (str(var), canonical_oracle_rung_text(text)) == wanted]
    if len(matches) != 1 or matches[0][0] not in ("HOLDS", "REFUTED"):
        return "UNDECIDED", None
    return matches[0]


def oracle_part_verdict_cache(rows, summary, refutations=None):
    """Return every unambiguous verdict proved by one part query.

    A state-exact assertion query evaluates the complete ladder for its
    selected variable.  Retaining only the candidate that caused the query
    would rerun the identical verifier job for every other rung.
    """
    if summary is None:
        return {}
    grouped = {}
    for var, text, verdict in rows or ():
        key = (str(var), canonical_oracle_rung_text(text))
        grouped.setdefault(key, []).append(str(verdict))
    return {
        key: (verdicts[0], (refutations or {}).get(key))
        for key, verdicts in grouped.items()
        if len(verdicts) == 1 and verdicts[0] in ("HOLDS", "REFUTED")
    }


def oracle_input_part_record(part):
    """Stable JSON record for one final oracle partition."""
    if not isinstance(part, OracleInputPart):
        raise TypeError("oracle input part record requires OracleInputPart")
    record = {
        "part_id": part.part_id,
        "region": {name: [str(lo), str(hi)] for name, (lo, hi) in part.region.items()},
        "holes": {name: [str(value) for value in values]
                  for name, values in part.holes.items()},
        "representative": {name: str(value) for name, value in part.witness.items()},
        "assertions": [{"var": candidate[0], "text": candidate[1]}
                       if isinstance(candidate, (tuple, list)) and len(candidate) == 2
                       else candidate for candidate in part.assertions],
        "depth": part.depth,
    }
    if part.representative_ce is not None:
        record["representative_ce"] = dict(part.representative_ce)
    if part.representative_claim is not None:
        record["representative_claim"] = dict(part.representative_claim)
    return record


def oracle_input_part_suffix(part):
    """Return a stable Solidity-identifier suffix for a physical part PUT."""
    if not isinstance(part, OracleInputPart):
        raise TypeError("oracle input part suffix requires OracleInputPart")
    suffix = re.sub(r"[^A-Za-z0-9_]+", "_", part.part_id).strip("_")
    if not suffix:
        suffix = "part"
    if suffix[0].isdigit():
        suffix = "p_" + suffix
    return f"part_{suffix}"


def oracle_input_part_ladder_rows(part):
    """Convert proved part assertions to build_put ladder rows.

    Non-generalized assertions such as R0/fixed replay markers are rendered by
    the normal PUT path.  Only verifier-proved R1/R2 rows are carried here.
    """
    if not isinstance(part, OracleInputPart):
        raise TypeError("oracle input part rows require OracleInputPart")
    rows = []
    seen = set()
    for assertion in part.assertions:
        if not isinstance(assertion, (tuple, list)) or len(assertion) != 2:
            continue
        var = str(assertion[0])
        text = canonical_oracle_rung_text(assertion[1])
        key = (var, text)
        if key in seen:
            continue
        seen.add(key)
        rows.append((var, text, "HOLDS"))
    return rows


def oracle_input_part_build_rows(base_rows, part, refined_candidates=None):
    """Rows to render for one physical oracle input part."""
    refined = {
        (str(candidate[0]), canonical_oracle_rung_text(candidate[1]))
        for candidate in (refined_candidates or ())
        if isinstance(candidate, (tuple, list)) and len(candidate) == 2
    }
    rows = []
    for row in base_rows or ():
        if not isinstance(row, (tuple, list)) or len(row) != 3:
            continue
        key = (str(row[0]), canonical_oracle_rung_text(row[1]))
        if key in refined:
            continue
        rows.append(row)
    rows.extend(oracle_input_part_ladder_rows(part))
    return rows


def merge_adjacent_oracle_parts(parts, coordinate_order=None):
    """Merge only rectangular neighbours with identical proved assertions."""
    current = sorted(list(parts or []), key=lambda part: tuple(
        part.region[name] for name in (coordinate_order or sorted(part.region))))
    changed = True
    while changed:
        changed = False
        merged = []
        index = 0
        while index < len(current):
            left = current[index]
            if index + 1 >= len(current):
                merged.append(left)
                break
            right = current[index + 1]
            differing = [name for name in left.region
                         if left.region.get(name) != right.region.get(name)]
            coordinate = differing[0] if len(differing) == 1 else None
            adjacent = (coordinate is not None and
                        left.region[coordinate][1] + 1 == right.region[coordinate][0])
            other_equal = (set(left.region) == set(right.region)
                           and left.assertions == right.assertions
                           and left.holes == right.holes)
            if not (adjacent and other_equal):
                merged.append(left)
                index += 1
                continue
            region = dict(left.region)
            region[coordinate] = (left.region[coordinate][0], right.region[coordinate][1])
            representative = left.witness
            merged.append(make_oracle_input_part(
                left.part_id + "+" + right.part_id, region, left.holes,
                representative,
                representative_ce=left.representative_ce,
                representative_claim=left.representative_claim,
                assertions=left.assertions,
                depth=min(left.depth, right.depth)))
            index += 2
            changed = True
        current = merged
    return current


def prepare_oracle_part_publications(parts, authenticate_representative):
    """Attach one authenticated fixed replay to every publishable child.

    ``authenticate_representative(part)`` returns an evidence dictionary or
    ``None``.  Missing evidence drops that child rather than borrowing another
    part's witness-specific assertions.
    """
    published, refused = [], []
    for part in parts or ():
        evidence = authenticate_representative(part)
        if not isinstance(evidence, dict) or evidence.get("authenticated") is not True:
            refused.append({"part_id": part.part_id,
                            "reason": "authenticated representative replay unavailable"})
            continue
        coordinates = evidence.get("coordinates")
        if coordinates != {name: str(value) for name, value in part.witness.items()}:
            refused.append({"part_id": part.part_id,
                            "reason": "representative replay does not match part witness"})
            continue
        published.append({"part": part, "representative": evidence})
    return published, refused


def oracle_part_materialization_plan(parts, authenticate_representative):
    """Return fail-closed physical PUT plans for publishable oracle parts."""
    published, refused = prepare_oracle_part_publications(parts, authenticate_representative)
    plans = []
    for entry in published:
        part = entry["part"]
        representative = entry["representative"]
        suffix = oracle_input_part_suffix(part)
        representative_ce = representative.get("ce")
        if not isinstance(representative_ce, dict):
            refused.append({
                "part_id": part.part_id,
                "reason": "authenticated representative replay lacks a complete CE",
            })
            continue
        plan = {
            "part": part,
            "suffix": suffix,
            "region": dict(part.region),
            "holes": {name: tuple(values) for name, values in part.holes.items()},
            "ladder_rows": oracle_input_part_ladder_rows(part),
            "representative_ce": {str(name): str(value)
                                  for name, value in representative_ce.items()},
            "representative": representative,
        }
        plans.append(plan)
    return plans, refused


class ConcreteFallback(Exception):
    """The certified region is valid but renders only one concrete replay."""

    def __init__(self, reason):
        super().__init__(reason)
        self.reason = reason


